"""Random valid-input generator + differential harness."""
import itertools, json, random, subprocess, sys
import ref

def canon(a,b): return (a,b) if a<b else (b,a)
G=ref.G

def pathlinks(q): return [canon(a,b) for a,b in zip(q,q[1:])]

def peel(agg):
    rnd={}; cur=dict(agg); r=0
    while cur:
        r+=1
        present=set()
        for q in cur: present.update(pathlinks(q))
        marked=set()
        for e in sorted(present):
            u,v=e; oku=okv=True
            for q in cur:
                if e not in pathlinks(q): continue
                if q[0]!=u and q[-1]!=u: oku=False
                if q[0]!=v and q[-1]!=v: okv=False
            if oku or okv: marked.add(e)
        if not marked: break
        for e in marked: rnd[e]=r
        nxt={}
        for q,c in cur.items():
            pl=pathlinks(q); s=0; t=len(q)
            if pl[0] in marked: s=1
            if pl[-1] in marked: t=len(q)-1
            if t-s>=2:
                k=q[s:t]; nxt[k]=nxt.get(k,0)+c
        cur=nxt
    return rnd, cur

def scopes_of(core, cur):
    idx={e:i for i,e in enumerate(core)}
    sc=[set() for _ in core]
    for q,c in cur.items():
        n=len(q)
        for i in range(n-1):
            a,b=q[i],q[i+1]; e=canon(a,b); ei=idx[e]
            sc[ei].add(ei)
            if a<b:
                L=(q[i-1],a) if i>0 else None
                R=(b,q[i+2]) if i+2<n else None
            else:
                L=(q[i+2],b) if i+2<n else None
                R=(a,q[i-1]) if i>0 else None
            for d in (L,R):
                if d is not None: sc[ei].add(idx[canon(d[0],d[1])])
    return [sorted(s) for s in sc]

def width_ok(ovars, scopes):
    m=len(ovars)
    live=[set() for _ in range(m)]
    for s in scopes:
        for x in s:
            for y in s:
                if x!=y: live[x].add(y); live[y].add(x)
    for v in ovars:
        nb=live[v]
        if len(nb)>4: return False
        nb=sorted(nb)
        for x in nb:
            for y in nb:
                if x!=y: live[x].add(y); live[y].add(x)
        for x in nb: live[x].discard(v)
        live[v]=set()
    return True

def find_order(core, cur):
    scopes=scopes_of(core, cur)
    m=len(core)
    if m<=7:
        for perm in itertools.permutations(range(m)):
            if width_ok(list(perm), scopes): return [list(core[i]) for i in perm]
        return None
    # greedy min-degree
    live=[set() for _ in range(m)]
    for s in scopes:
        for x in s:
            for y in s:
                if x!=y: live[x].add(y); live[y].add(x)
    remaining=set(range(m)); out=[]
    while remaining:
        best=min(remaining, key=lambda v:(len(live[v]),v))
        if len(live[best])>4: return None
        nb=sorted(live[best])
        for x in nb:
            for y in nb:
                if x!=y: live[x].add(y); live[y].add(x)
        for x in nb: live[x].discard(best)
        live[best]=set(); remaining.discard(best); out.append(best)
    if not width_ok(out, scopes): return None
    return [list(core[i]) for i in out]

def gen(rng, maxcore=7):
    n=rng.randint(3,9)
    nodes=list(range(1, n+1))
    edges=set()
    # random spanning structure
    order=nodes[:]
    rng.shuffle(order)
    for i in range(1,n):
        a=order[i]; b=order[rng.randrange(i)]
        edges.add(canon(a,b))
    for _ in range(rng.randint(0,4)):
        a,b=rng.sample(nodes,2)
        edges.add(canon(a,b))
    edges=sorted(edges)
    adj={x:[] for x in nodes}
    for a,b in edges: adj[a].append(b); adj[b].append(a)
    ixps=[rng.randint(500,520) for _ in range(rng.randint(0,2))]
    ixps=list(dict.fromkeys(ixps))
    rib=[]
    for _ in range(rng.randint(1,10)):
        start=rng.choice(nodes); p=[start]
        for _ in range(rng.randint(1,5)):
            nxt=rng.choice(adj[p[-1]])
            p.append(nxt)
        # remove adjacent dups not needed (walk may revisit -> loop, allowed occasionally)
        c=rng.choice([1,1,2,3,5,7,11,1000000])
        # sprinkle ixps
        q=[]
        for x in p:
            if ixps and rng.random()<0.15: q.append(rng.choice(ixps))
            if rng.random()<0.15: q.append(x)
            q.append(x)
        if len(q)>64: q=q[:64]
        rib.append({'path':q,'count':c})
    # aggregate-normalize to find core
    ixpset=set(ixps)
    def norm(p):
        out=[]
        for a in p:
            if a in ixpset: continue
            if out and out[-1]==a: continue
            out.append(a)
        return out
    agg={}
    for rec in rib:
        q=norm(rec['path'])
        if len(q)<2 or len(set(q))!=len(q): continue
        agg[tuple(q)]=agg.get(tuple(q),0)+rec['count']
    links=set()
    for q in agg: links.update(pathlinks(q))
    rnd,cur=peel(agg)
    core=sorted(links-set(rnd))
    if len(core)>maxcore: return None
    order=find_order(core,cur)
    if order is None: return None
    priors=[]; used=set()
    allpairs=set(edges)|set(links)
    for _ in range(rng.randint(0,4)):
        if not allpairs: break
        e=rng.choice(sorted(allpairs))
        if e in used: continue
        used.add(e)
        if rng.random()<0.5: e=(e[1],e[0])
        w=[rng.randint(0,10) for _ in range(3)]
        if sum(w)==0: w[0]=1
        priors.append({'link':list(e),'weights':w})
    declared=[]; usedd=set()
    for _ in range(rng.randint(0,3)):
        if not allpairs: break
        e=rng.choice(sorted(allpairs))
        if e in usedd: continue
        usedd.add(e)
        if rng.random()<0.5: e=(e[1],e[0])
        declared.append({'link':list(e),'rel':rng.choice(['c2p','p2p','p2c'])})
    queries=[]
    qn=rng.randint(0,6)
    for i in range(qn):
        if rng.random()<0.7 and adj:
            start=rng.choice(nodes); p=[start]
            for _ in range(rng.randint(0,5)):
                p.append(rng.choice(adj[p[-1]]))
        else:
            p=[rng.randint(1,1000) for _ in range(rng.randint(0,5))]
        if rng.random()<0.15 and ixps:
            p=p+[rng.choice(ixps)]
        a=rng.randint(0,10); b=rng.randint(a,10) if a else rng.randint(1,10)
        if b<a: a,b=b,a
        queries.append({'id':'q%d'%i,'path':p,'threshold':[a,b if b>=a else a]})
    return {'version':1,'ixps':ixps,'rib':rib,'priors':priors,'declared':declared,'order':order,'queries':queries}
