import json, random, subprocess, sys, importlib.util
sys.path.insert(0,'/workspace/tmp')
import gen, ref
spec = importlib.util.spec_from_file_location("main", "/workspace/submission/main.py")
main = importlib.util.module_from_spec(spec); spec.loader.exec_module(main)

def close(a,b):
    if type(a) is dict:
        return set(a)==set(b) and all(close(a[k],b[k]) for k in a)
    if type(a) is list:
        return type(b) is list and len(a)==len(b) and all(close(x,y) for x,y in zip(a,b))
    if type(a) is float:
        return type(b) in (int,float) and abs(a-b)<=1e-9
    return type(a) is type(b) and a==b

seed=int(sys.argv[1]) if len(sys.argv)>1 else 0
N=int(sys.argv[2]) if len(sys.argv)>2 else 200
rng=random.Random(seed)
tested=0; skipped=0; zero=0
for it in range(N*10):
    if tested>=N: break
    data=gen.gen(rng)
    if data is None:
        skipped+=1; continue
    try:
        exp=ref.solve(data)
    except AssertionError as e:
        skipped+=1; continue
    if exp.get('error')=='zero-partition': zero+=1
    got=main.solve(json.loads(json.dumps(data)))
    tested+=1
    if not close(exp,got):
        print("MISMATCH seed",seed,"iter",it)
        print(json.dumps(data,indent=1))
        print("expected",json.dumps(exp,indent=1))
        print("got     ",json.dumps(got,indent=1))
        sys.exit(1)
print("tested",tested,"skipped",skipped,"zero-partition",zero)
